const BIO_MISSIONS=[{"id": "30", "name": "Dente de Orc", "required": 10, "image": "assets/bio-30.png"}, {"id": "40", "name": "Livro da Maldição", "required": 15, "image": "assets/bio-40.png"}, {"id": "50", "name": "Lembrança do Demónio", "required": 15, "image": "assets/bio-50.png"}, {"id": "60", "name": "Mármore de Gelo", "required": 20, "image": "assets/bio-60.png"}, {"id": "70", "name": "Ramo de Zelkova", "required": 25, "image": "assets/bio-70.png"}, {"id": "80", "name": "Certificado de Tugyi", "required": 30, "image": "assets/bio-80.png"}, {"id": "85", "name": "Ramo Vermelho", "required": 40, "image": "assets/bio-85.png"}, {"id": "90", "name": "Nota do Líder", "required": 50, "image": "assets/bio-90.png"}, {"id": "92", "name": "Jóia da Malevolência", "required": 10, "image": "assets/bio-92.png"}, {"id": "94", "name": "Jóia da Sabedoria", "required": 20, "image": "assets/bio-94.png"}];
function currentBioQuest(c){const selected=c.bio.currentQuest;if(selected!==undefined)return BIO_MISSIONS.find(q=>q.id===selected)||null;return BIO_MISSIONS.find(q=>Number(q.id)<=Number(c.level)&&(Number(q.id)<92?!c.bio.completed?.includes(Number(q.id)):!['hp','defense','attack'].includes(c.bio['choice'+q.id])))||null;}
function bioCount(b,q){const n=b.deliveries?.[q?.id];return Number.isInteger(n)&&n>=0&&n<=q.required?n:null;}
function renderBiologist(){const c=char(),b=c.bio,q=currentBioQuest(c),count=q?bioCount(b,q):null;$('#bio').innerHTML=`<div class="feature"><strong>${esc(b.last)}</strong>${b.reward?`<p>${esc(b.reward)}</p>`:''}${b.notes?`<p>${esc(b.notes)}</p>`:''}</div>${q?`<div class="bio-delivery"><div class="bio-item"><img src="${q.image}" alt="${esc(q.name)}"></div><div><small>MISSÃO NÍVEL ${q.id}</small><strong>${esc(q.name)}</strong><div class="bio-count">${count===null?'—':count}<span> / ${q.required}</span></div><small>Entregas com sucesso${count===null?' · por preencher':''}</small></div></div><div class="bio-counter-actions"><button data-bio-delta="-1" ${readonly||count===null||count===0?'disabled':''} aria-label="Retirar uma entrega">−</button><button data-bio-delta="1" ${readonly||count===q.required?'disabled':''}>＋ Entrega</button></div><p class="hint">A contagem não conclui a missão nem atribui a recompensa.</p>`:'<p class="hint">Sem missão atual selecionada.</p>'}`;}
function bioProgressFields(c){const q=currentBioQuest(c),count=q?bioCount(c.bio,q):null;return `<div class="editor-section full"><h3>Entrega atual</h3></div>`+selectPairs('bioCurrent','Missão atual',q?.id||'',[['','Sem missão'],...BIO_MISSIONS.filter(q=>Number(q.id)<=Number(c.level)).map(q=>[q.id,'Nível '+q.id+' · '+q.name])])+field('bioCount','Entregas com sucesso',count??'','number')+`<p class="hint full" id="bioCountHint">${q?'Máximo '+q.required+' entregas.':'Seleciona uma missão.'} Deixa vazio se não sabes a contagem.</p>`;}
function readBioProgress(v,b){const q=BIO_MISSIONS.find(q=>q.id===v.bioCurrent);if(v.bioCurrent&&(!q||Number(q.id)>Number(char().level)))throw Error('Escolhe uma missão disponível para este nível.');if(v.bioCount!==''&&(!q||!Number.isInteger(Number(v.bioCount))||Number(v.bioCount)<0||Number(v.bioCount)>q.required))throw Error('A contagem deve ficar entre 0 e '+(q?.required??0)+'.');const deliveries={...b.deliveries};if(q){if(v.bioCount==='')delete deliveries[q.id];else deliveries[q.id]=Number(v.bioCount);}return {currentQuest:v.bioCurrent,deliveries};}
document.addEventListener('change',e=>{if(e.target.name!=='bioCurrent')return;const q=BIO_MISSIONS.find(q=>q.id===e.target.value);$('[name="bioCount"]').value=q?bioCount(char().bio,q)??'':'';$('#bioCountHint').textContent=q?'Máximo '+q.required+' entregas. Deixa vazio se não sabes a contagem.':'Sem missão selecionada.';});
document.addEventListener('click',e=>{const b=e.target.closest('[data-bio-delta]');if(!b||readonly)return;const q=currentBioQuest(char());if(!q)return;const old=bioCount(char().bio,q),delta=Number(b.dataset.bioDelta);if(![-1,1].includes(delta)||(old===null&&delta<0))return;const next=Math.max(0,Math.min(q.required,(old??0)+delta));char().bio.deliveries={...char().bio.deliveries,[q.id]:next};save();});
