function spiritMatch(line){const m=String(line||'').trim().match(/^(.*?)\s*\+(\d+)\s*$/);if(!m)return null;const n=normalized(m[1]).replace('pedra do golpe','pedra de golpe').replace('pedra de anti-','pedra anti-');const name=Object.keys(spiritCatalog()).find(k=>normalized(k)===n);return name?{name,level:+m[2],...spiritCatalog()[name]}:null;}
function spiritNames(slot,it){return Object.entries(spiritCatalog()).filter(([n,e])=>e.slots.includes(slot)&&(n!=='G. Pedra Anti-Monstros'||itemMinimumLevel(it)>=120)).map(([n])=>n);}
function itemMinimumLevel(it){return Number(fixedAttributes(it||{}).text.match(/Para nível:\s*(\d+)/i)?.[1]||0);}
function spiritValue(p){const value=p?.values[p.level];return value===undefined||value===null?'':p.label+': +'+value+p.unit+(p.name==='Pedra Demoníaca Poder'?' / +'+(value*2):'');}
function validateStones(v,slot,old){const text=readStones(v),allowed=spiritNames(slot,{catalogId:v.catalogId,slot,upgrade:v.upgrade,fixedMode:v.fixedMode,fixedManual:v.fixedManual});if(text===(old?.stones||'')&&v.catalogId===catalogueId(old))return text;const seen=[];for(const line of text.split('\n').filter(Boolean)){const p=spiritMatch(line);if(!p||!allowed.includes(p.name)||!spiritValue(p))throw Error('Escolhe uma pedra compatível com este equipamento.');if(seen.includes(p.name))throw Error('Não podes repetir a mesma pedra.');seen.push(p.name);}return text;}
function refinementEntry(it){return window.REFINEMENT_CATALOG?.[catalogueId(it)];}
function refinementText(it){const e=refinementEntry(it),n=Number(it.refinedSockets?.count||0);if(!n||it.refinedSockets.material!==e?.material)return '';return (e.levels[String(it.upgrade||'').replace(/^\+/,'')]||[]).slice(0,n).join('\n');}
function refinementBlock(it){const e=refinementEntry(it),text=refinementText(it);if(!text)return '';return `<div class="refinement-summary"><img src="${esc(e.image)}" alt="${esc(e.material)}"><div><span class="bonus-section-label">Refinamentos ativos · ${esc(it.refinedSockets.count)}/3</span><strong>${esc(e.material)}</strong><pre>${esc(text)}</pre></div></div>`;}
function refinementFields(it,k){if(!['earrings','necklace','bracelet','belt'].includes(k))return '';const e=refinementEntry(it);return `<div class="editor-section full"><h3>Materiais refinados</h3><p>O material é definido pelo item. Conta apenas as gemas ainda ativas; o tempo restante não é simulado.</p></div><div class="full" id="refinementEditor">${refinementEditor(it,e)}</div>`;}
function refinementEditor(it,e){return e?`<div class="refinement-heading"><img src="${esc(e.image)}" alt=""><strong>${esc(e.material)}</strong></div>`+selectPairs('refinedCount','Gemas ativas',it?.refinedSockets?.material===e.material?it.refinedSockets.count:0,[0,1,2,3].map(n=>[n,n+' / 3']))+`<input type="hidden" name="refinedMaterial" value="${esc(e.material)}">`:'<p class="hint">Escolhe um equipamento com tabela de gemas. Sem tabela verificada, não se atribuem valores automáticos.</p>';}
function syncRefinementEditor(reset=false){const box=$('#refinementEditor');if(!box||!$('#modal').open)return;const v=Object.fromEntries(new FormData($('#form'))),it={catalogId:v.catalogId,name:v.name,slot:$('#form').dataset.slot,upgrade:v.upgrade},e=refinementEntry(it);it.refinedSockets={material:v.refinedMaterial,count:reset?0:Number(v.refinedCount||0)};box.innerHTML=refinementEditor(it,e);}
function readRefinement(v,it){const e=refinementEntry(it),count=Number(v.refinedCount||0);if(!Number.isInteger(count)||count<0||count>3)throw Error('Escolhe entre zero e três gemas.');if(count&&(!e||v.refinedMaterial!==e.material||!e.levels[String(it.upgrade).replace(/^\+/,'')]))throw Error('O refinamento não corresponde ao equipamento ou ao melhoramento.');return e?{material:e.material,count}:undefined;}
function initialAttributes(c){return ({Guerreiro:{str:6,vit:4,int:3,dex:3},Ninja:{str:4,vit:3,int:3,dex:6},Sura:{str:5,vit:3,int:5,dex:3},'Xamã':{str:3,vit:4,int:6,dex:3},Lycan:{str:2,vit:6,int:2,dex:6}})[c.class]||{str:5,vit:3,int:5,dex:3};}
function attributeBudget(c,bubbles=0){return +c.level>90?270:Math.max(0,(Math.min(90,+c.level)-1)*3+Math.min(3,Math.max(0,+bubbles)));}
function priorityAttributes(c,bubbles=0){const a={...initialAttributes(c)};let remaining=attributeBudget(c,bubbles);for(const k of ['int','vit','dex','str']){const add=Math.min(90-a[k],remaining);a[k]+=add;remaining-=add;}return a;}
function editStatus(){const c=char(),s=set(),p=c.statusProfile||{},a=p.attributes||initialAttributes(c),fx=s.statusEffects||{};open('Status · base e efeitos',selectPairs('mode','Mostrar no painel',s.statusMode||'auto',[['auto','Calculado · assinalar dados em falta'],['manual','Referência manual guardada']])+selectPairs('bubbles','Bolas de EXP preenchidas neste nível',p.bubbles||0,[0,1,2,3].map(n=>[n,n]))+`<div class="editor-section full"><h3>Atributos sem equipamento</h3><p>Máximo natural: 90. Até ao nível 90 e 75% de EXP: 270 pontos ganhos, além dos 16 iniciais. Redistribuições podem alterar os mínimos.</p><button type="button" id="priorityAttrs">Preencher INT → VIT → DES → FRÇ</button></div>`+Object.entries({str:'Força (FRÇ)',vit:'Vitalidade (VIT)',int:'Inteligência (INT)',dex:'Destreza (DES)'}).map(([k,n])=>field(k,n,a[k],'number')).join('')+field('hpGrowth','HP ganhos pelos níveis (sem VIT, itens ou Biólogo)',p.hpGrowth??'','number')+`<p class="hint full">HP ganhos pelos níveis variam entre 36 e 44 por nível. Para obter este campo a partir do jogo: tira equipamento e todos os efeitos; ao HP restante subtrai o HP inicial da classe, 40 × VIT e as recompensas de HP do Biólogo. Sura: HP inicial 650.</p>`+field('defenseBase','Defesa natural no jogo, sem itens, buffs ou Biólogo (opcional)',p.defenseBase??'','number')+selectPairs('alchemyActive','Alquimia ativa',fx.alchemyActive?'yes':'no',[['no','Não'],['yes','Sim']])+selectPairs('petActive','Pet invocado',fx.petActive?'yes':'no',[['no','Não'],['yes','Sim']])+field('extra','Efeitos adicionais ativos',fx.extra||'','textarea')+`<p class="hint full">Regista aqui valores confirmados de buffs, montada, energia ou ressonância, por exemplo: Valor de Ataque: 300 ou Probabilidade de golpes críticos: 10%. Efeitos percentuais complexos são assinalados para validação. As skills registadas não são ativadas automaticamente.</p><button type="button" id="manualStatus" class="full">Editar referência manual preservada</button>`,v=>{const attrs=Object.fromEntries(['str','vit','int','dex'].map(k=>[k,Number(v[k])]));if(Object.values(attrs).some(n=>!Number.isInteger(n)||n<1||n>90))throw Error('Os atributos base devem ser inteiros entre 1 e 90.');const budget=attributeBudget(c,v.bubbles)+16;if(Object.values(attrs).reduce((a,b)=>a+b,0)>budget)throw Error('A distribuição ultrapassa os pontos disponíveis ('+budget+').');if(v.defenseBase!==''&&(!Number.isInteger(+v.defenseBase)||+v.defenseBase<0))throw Error('A defesa natural deve ser um inteiro positivo.');if(v.hpGrowth!==''&&(!Number.isInteger(+v.hpGrowth)||+v.hpGrowth<36*(+c.level-1)||+v.hpGrowth>44*(+c.level-1)))throw Error('O crescimento de HP deve ficar entre '+36*(+c.level-1)+' e '+44*(+c.level-1)+'.');c.statusProfile={...p,attributes:attrs,growthLevel:+c.level,bubbles:+v.bubbles,defenseBase:v.defenseBase===''?null:Number(v.defenseBase),hpGrowth:v.hpGrowth===''?null:+v.hpGrowth};s.statusMode=v.mode;s.statusEffects={...fx,alchemyActive:v.alchemyActive==='yes',petActive:v.petActive==='yes',extra:v.extra};});}
function editBiologist(){const b=char().bio,r=b.completed||[];open('Biólogo',bioProgressFields(char())+field('last','Descrição atual',b.last)+field('reward','Recompensa / descrição',b.reward)+field('notes','Notas',b.notes,'textarea')+`<div class="editor-section full"><h3>Missões entregues · cálculo automático</h3><p>Confirma as missões concluídas. O texto antigo mantém-se e não é convertido em recompensas presumidas.</p></div>`+[30,40,50,60,70,80,85,90].map(n=>selectPairs('bio'+n,'Missão nível '+n,r.includes(n)?'yes':'no',[['no','Não concluída'],['yes','Concluída']])).join('')+[92,94].map(n=>selectPairs('bio'+n,'Missão nível '+n+' · recompensa',b['choice'+n]||'',[['','Por confirmar / não concluída'],['none','Não concluída'],['hp','HP +'+(n===92?1000:1100)],['defense','Defesa +'+(n===92?120:140)],['attack','Ataque +'+(n===92?51:60)]])).join(''),v=>{const progress=readBioProgress(v,b);for(const n of [30,40,50,60,70,80,85,90,92,94])if((v['bio'+n]==='yes'||['hp','defense','attack'].includes(v['bio'+n]))&&Number(char().level)<n)throw Error('A personagem ainda não tem nível para a missão '+n+'.');Object.assign(b,{...progress,last:v.last,reward:v.reward,notes:v.notes,completed:[30,40,50,60,70,80,85,90].filter(n=>v['bio'+n]==='yes'),choice92:v.bio92,choice94:v.bio94});});}
function statusAccumulator(){return {hp:0,hpPct:0,attack:0,attackMax:0,attackPct:0,defense:0,defensePct:0,block:0,crit:0,pierce:0,str:0,vit:0,int:0,dex:0,fire:0,lightning:0,wind:0,ice:0,earth:0,dark:0,powerFire:0,powerLightning:0,powerWind:0,powerIce:0,powerEarth:0,powerDark:0,powerAll:0,attackSpeed:0,magicResist:0,magicDefense:0,arrowEvade:0,precision:0};}
function statusLabel(label){const n=normalized(label).replace(/[.:%()+]/g,'').replace(/\s+/g,' ').trim().replace(/^resistencia (?:contra|a|ao|aos) /,'resistencia ').replace(/^golpes criticos$/,'probabilidade de golpes criticos').replace(/^golpes perfurantes$/,'probabilidade de golpes perfurantes').replace(/^crit$/,'probabilidade de golpes criticos').replace(/^furos$/,'probabilidade de golpes perfurantes').replace(/escuridao/g,'trevas');const power=Object.entries(elementKinds()).find(([name,e])=>n.startsWith('poder ')&&(n.includes(normalized(name))||(name==='Raios'&&n.includes('relampagos'))));if(power)return 'power'+power[1].key[0].toUpperCase()+power[1].key.slice(1);if(n==='poder elemental')return 'powerAll';const names={precision:['precisao'],attackSpeed:['rapidez de ataque','velocidade de ataque'],magicResist:['resistencia magia','resistencia magias','resistencia magica','defesa contra magias','defesa magias'],magicDefense:['defesa magica','valor de defesa magica'],arrowEvade:['evitar flechas','probabilidade de evitar flechas','possibilidade de evitar flechas'],str:['forca','str','frc'],vit:['vitalidade','vit'],int:['inteligencia','int'],dex:['destreza','dex','des'],hp:['max hp','max vd','hp','vd'],defense:['defesa','valor de defesa'],attack:['valor de ataque','va','ataque'],block:['probabilidade de bloquear ataques fisicos','chance de bloquear ataques fisicos','bloquear ataques fisicos','bloquear ataques corporais'],crit:['probabilidade de golpes criticos','chance de golpe critico','ch g critico','ch golpe critico'],pierce:['probabilidade de golpes perfurantes','chance de golpe furado','ch gfurado','ch g furado','ch golpe furado'],fire:['resistencia fogo'],lightning:['resistencia relampagos'],wind:['resistencia vento'],ice:['resistencia gelo'],earth:['resistencia terra'],dark:['resistencia trevas']};return Object.keys(names).find(k=>names[k].includes(n));}
function parseStatusText(text,target,source,unknown,records){for(const raw of String(text||'').split('\n').filter(x=>x.trim())){let line=raw.trim();if(/Ganha Poder (?:do )?Gelo(?: por 5s em combate|:\s*\+?5\s*seg\.?)/i.test(line)||/Absorve\s+1%\s+do dano como MN/i.test(line)||/^(Defesa contra perda de sentidos|Imune a perda de sentidos|Imunidade a perda de sentidos)\s*(?::\s*Sim)?$/i.test(line))continue;const prefix=line.match(/^([+-]?\d+(?:[.,]\d+)?)\s*(%)?\s+(.+)$/);if(prefix)line=prefix[3]+': '+prefix[1]+(prefix[2]||'');if(/^Para n[ií]vel|^N[ií]vel/i.test(line))continue;const m=line.match(/^(.*?)(?:\s*:\s*|\s+|(?=\+))([+-]?\d+(?:[.,]\d+)?(?:\s*[-–]\s*\d+(?:[.,]\d+)?)?(?:\s*\(\+\d+\))?)\s*(%)?\s*$/);if(!m){unknown.push(source+' · '+line);continue;}const label=m[1].trim(),k=statusLabel(label),pct=!!m[3]||label.includes('%');if(!k){if(/condicion|quando|durante|se /i.test(label))unknown.push(source+' · '+line);continue;}const nums=m[2].match(/\d+(?:[.,]\d+)?/g).map(n=>Number(n.replace(',','.'))),negative=m[2].startsWith('-'),n=(negative?-1:1)*nums[0];let key=k;if(pct&&['hp','attack','defense'].includes(k))key=k+'Pct';else if(pct&&['str','vit','int','dex'].includes(k)){unknown.push(source+' · '+line);continue;}target[key]+=n;if(k==='attack'&&!pct){target.attackMax+=nums.length>1&&/\d\s*[-–]\s*\d/.test(m[2])?nums[1]:n;if(m[2].includes('(')){const extra=nums[nums.length-1];target.attack+=extra;target.attackMax+=extra;}}records.push({source,label,value:m[2]+(pct?'%':''),key});}}
function calculateStatus(c=char(),s=set()){
 const totals=statusAccumulator(),unknown=[],records=[],fx=s.statusEffects||{},profile=c.statusProfile,base=profile?.attributes;let weapon=[0,0],gearDefense=0,hpParts=null;const add=(text,source)=>parseStatusText(text,totals,source,unknown,records);
 for(const [slot,id] of Object.entries(s.items)){const original=item(id),it=original?effectiveAbsorption(original):null;if(!it){unknown.push('Item em falta: '+slot);continue;}const beforeDefense=totals.defense;if(slot==='mount'){if(it.mounted){add(mountBonuses(it),it.name);gearDefense+=totals.defense-beforeDefense;}continue;}const fixed=fixedAttributes(it);if(!fixed.text&&!['sash','aura','mount','arrows','skin','hair','costume'].includes(slot))unknown.push(it.name+' · faltam atributos fixos');const acc=statusAccumulator(),local=[];parseStatusText([fixed.text,elementalBase(it),elementalText(it).split('\n').filter(l=>!/^Valor de Ataque:/i.test(l)).join('\n')].filter(Boolean).join('\n'),acc,it.name,unknown,local);if(slot==='weapon'){weapon[0]+=acc.attack;weapon[1]+=acc.attackMax;acc.attack=acc.attackMax=0;}Object.keys(totals).forEach(k=>totals[k]+=acc[k]);records.push(...local);if(slot==='weapon'&&Number(it.elemental?.attack)>0)add('Valor de Ataque: '+Number(it.elemental.attack),it.name+' · encantamento elemental');const absorbed=absorbedStatusParts(it);weapon[0]+=absorbed.weapon[0];weapon[1]+=absorbed.weapon[1];if(absorbed.weapon.some(Boolean))records.push({source:it.name+' · base absorvida',label:'Ataque na fórmula da arma',value:absorbed.weapon.join('–'),key:'weaponBase'});add([it.bonuses,it.bonus6,it.bonus7,absorbed.text,refinementText(it)].filter(Boolean).join('\n'),it.name);if(it.refinedSockets?.count&&!refinementText(it))unknown.push(it.name+' · refinamento sem tabela compatível');for(const line of String(it.stones||'').split('\n').filter(Boolean)){const p=spiritMatch(line);if(p&&spiritNames(slot,it).includes(p.name)&&spiritValue(p)&&p.name!=='Pedra Demoníaca Poder')add(spiritValue(p),it.name+' · '+p.name);else unknown.push(it.name+' · pedra não calculada: '+line);}gearDefense+=totals.defense-beforeDefense;}
 const activeMount=item(s.items.mount);let horseVit=0;if(activeMount?.mounted){const horse=Number(c.progress?.horse),floors=window.HORSE_ATTRIBUTES[String(Math.min(30,horse))];if(base&&floors&&Number.isInteger(horse)&&horse>=1&&horse<=40){for(const k of ['str','vit','int','dex']){const extra=Math.max(0,floors[k]-Number(base[k]));totals[k]+=extra;if(k==='vit')horseVit=extra;if(extra)records.push({source:'Montado · cavalo nível '+horse,label:k.toUpperCase(),value:'+'+extra,key:k});}}else unknown.push('Montado: confirma um nível de cavalo entre 1 e 40.');}for(const key of ['Fire','Lightning','Wind','Ice','Earth','Dark'])totals['power'+key]+=totals.powerAll;
 const bio=c.bio;if(!Array.isArray(bio.completed))unknown.push('Confirma as missões concluídas do Biólogo');else{if(bio.completed.includes(40))add('Rapidez de Ataque: 5%','Biólogo 40');if(bio.completed.includes(80))add('Rapidez de Ataque: 6%','Biólogo 80');if(bio.completed.includes(50))add('Defesa: 60','Biólogo 50');if(bio.completed.includes(60))add('Valor de Ataque: 50','Biólogo 60');}
 let bioHP=0;for(const n of [92,94]){const choice=bio['choice'+n];if(+c.level>=n&&!choice)unknown.push('Confirma a recompensa do Biólogo '+n);if(choice==='hp')bioHP+=n===92?1000:1100;else if(choice==='defense')add('Defesa: '+(n===92?120:140),'Biólogo '+n);else if(choice==='attack')add('Valor de Ataque: '+(n===92?51:60),'Biólogo '+n);}
 if(fx.alchemyActive){c.alchemy.stones.forEach((g,i)=>{if(g.available===false)return;const entry=gemEntry(g,i),cat=window.ALCHEMY_CATALOG[alchemyKinds[i]];if(!entry){if(gemConfig(g).cl>=0)unknown.push(g.name+' · falta tabela');return;}add(entry.fixed.join('\n'),'Alquimia · '+g.name);add(gemChoices(g,i).map(id=>cat.labels[id]+': '+entry.extra[id]).join('\n'),'Alquimia · '+g.name);if(gemNotes(g,i))unknown.push(g.name+' · confirmar bónus: '+gemNotes(g,i));});const resonance=alchemySetInfo(c);if(resonance.active)c.alchemy.stones.forEach((g,i)=>add(alchemySetLines(c,i).join('\n'),'Ressonância '+resonance.name+' · '+g.name));if(resonance.active&&resonance.cl===5&&gemChoices(c.alchemy.stones[0],0).includes('b4'))unknown.push('Ressonância · Defesa do Rubi mítico: wiki PT indica +90, wiki IT indica +60; usado +90 da fonte PT.');if(!resonance.active&&c.alchemy.stones.slice(0,6).some(g=>[2,3].includes(gemConfig(g).cl)))unknown.push('Ressonância: falta tabela para conjuntos raros/antigos.');}
 if(fx.petActive){const p=c.pet||{},hp=Number(String(p.hp||0).replace(',','.'));if(hp)add('Máx. HP: '+hp+'%','Pet · HP');for(const line of String(p.skills||'').split('\n').filter(Boolean)){const m=line.match(/^(.*?)\s+(\d+)\s*$/),name=m?.[1],lv=m?.[2],value=petSkillEffect(p,name,lv).value;if(value===null){if(['Enfurecido','Perfuração','Baluarte'].includes(name))unknown.push('Pet · '+name+' '+lv+': confirma a percentagem no editor do pet');continue;}const labels={'Enfurecido':'Valor de Ataque','Perfuração':'Probabilidade de golpes perfurantes','Baluarte':'Probabilidade de bloquear ataques físicos'};if(labels[name]&&name!=='Enfurecido')add(labels[name]+': '+value+'%','Pet · '+name+' '+lv);else records.push({source:'Pet · '+name+' '+lv,label:name,value:value+'%',key:'petSkill'});}}
 add(fx.extra,'Efeito adicional');let attributes=null;if(base)attributes=Object.fromEntries(['str','vit','int','dex'].map(k=>[k,+base[k]+totals[k]]));else unknown.push('Configura os quatro atributos base da personagem');
 const activeSkills=skillEffects(c,attributes);for(const [name,effect] of Object.entries(activeSkills)){if(!fx.skillActive?.[name])continue;if(!effect.k||(['Lâmina Encantada','Armadura Negra'].includes(name)&&!attributes)){unknown.push(name+' · confirma o nível da habilidade e os atributos base');continue;}if(name==='Lâmina Encantada')add('Valor de Ataque: '+effect.attack,name+' '+effect.level);if(name==='Armadura Negra')add('Defesa: '+effect.defense,name+' '+effect.level);if(name==='Receio'){add('Evitar Flechas: '+effect.avoid+'%',name+' '+effect.level);records.push({source:name+' '+effect.level,label:'Redução do ataque inimigo',value:effect.reduction+'%',key:'fearReduction'});}}
 const precisionLevel=exactSkillLevel(c.progress?.accuracy);if(precisionLevel===null)unknown.push('Precisão · confirma o nível da habilidade');else if(skillIndex(precisionLevel))add('Precisão: '+PRECISION_VALUES[skillIndex(precisionLevel)],'Precisão '+precisionLevel);
 const result={...totals,attackSpeed:Math.min(200,100+totals.attackSpeed),magicDefense:null,hp:null,attack:null,attackMax:null,defense:null};const level=+c.level;if(profile?.growthLevel&&profile.growthLevel!==level)unknown.push('O nível mudou: volta a confirmar os HP ganhos pelos níveis');if(attributes){result.magicDefense=Math.floor(level+attributes.vit/3+attributes.int+gearDefense/2)+totals.magicDefense;result.defense=(profile.defenseBase!==null&&profile.defenseBase!==undefined?Number(profile.defenseBase):level+Math.floor(attributes.vit*0.8))+totals.defense;if(profile.defenseBase===null||profile.defenseBase===undefined)unknown.push('Defesa natural: fórmula da wiki italiana; confirma o valor sem equipamento para validar diferenças entre fontes');else if(totals.vit){result.defense+=Math.floor(attributes.vit*.8)-Math.floor(base.vit*.8);unknown.push('Confirma o arredondamento da defesa com VIT adicional nos itens');}const stat=c.class==='Ninja'?attributes.dex:c.class==='Xamã'?attributes.int:attributes.str,ar=Math.min(100,70+Math.floor((level+2*attributes.dex)/9));const atk=n=>Math.floor(2*level+ar/75*((attributes.str+n)+(stat+n)/2));result.attack=atk(weapon[0])+totals.attack;result.attackMax=atk(weapon[1])+totals.attackMax;if(c.class==='Lycan'){result.attack=result.attackMax=null;unknown.push('Fórmula de ataque do Lycan ainda não verificada');}
  const initialHP=({Guerreiro:600,Ninja:650,Sura:650,'Xamã':700})[c.class];if(initialHP!==undefined&&profile.hpGrowth!==null&&profile.hpGrowth!==undefined&&(!profile.growthLevel||profile.growthLevel===level)){const natural=initialHP+Number(profile.hpGrowth)+40*attributes.vit+bioHP;result.hp=natural+Math.floor(natural*totals.hpPct/100)+totals.hp;hpParts={initial:initialHP,growth:Number(profile.hpGrowth),vit:40*attributes.vit,bio:bioHP,natural,percent:Math.floor(natural*totals.hpPct/100),flat:totals.hp};}else unknown.push('Configura os HP ganhos pelos níveis para calcular HP');}
 if(horseVit){result.hp=null;unknown.push('Montado: confirmar o efeito da VIT do cavalo no HP.');}
 if(totals.attackPct){unknown.push('Ataque percentual: '+totals.attackPct+'% requer confirmação do efeito no painel do jogo');result.attack=result.attackMax=null;}// Talismans' Defesa % is a damage-reduction bonus and does not raise displayed defense.

 if(unknown.some(n=>n.includes('valor entre parênteses')))result.attack=result.attackMax=null;if(fx.petActive){const p=c.pet||{};if(Number(p.hp))unknown.push('Pet · HP percentual aplicado à base natural, como Máx. HP %; confirma o total no jogo.');const def=Number(String(p.defense||0).replace(',','.'));if(def&&result.defense!==null){const gain=Math.floor(result.defense*def/100);result.defense+=gain;records.push({source:'Pet',label:'Defesa adicional',value:'+'+gain+' ('+def+'%)',key:'defense'});}for(const line of String(p.skills||'').split('\n')){const m=line.match(/^Enfurecido\s+(\d+)\s*$/);if(!m)continue;const value=petSkillEffect(p,'Enfurecido',m[1]).value;if(value===null){result.attack=result.attackMax=null;continue;}if(result.attack!==null){result.attack+=Math.floor(result.attack*value/100);result.attackMax+=Math.floor(result.attackMax*value/100);unknown.push('Pet · Enfurecido aplicado ao ataque total: confirma o arredondamento no jogo.');}}for(const name of ['Perfuração','Baluarte'])for(const line of String(p.skills||'').split('\n')){const m=line.match(/^(.*?)\s+(\d+)\s*$/);if(m?.[1]===name&&petSkillEffect(p,name,m[2]).value===null)result[name==='Perfuração'?'pierce':'block']=null;}}
 result.evasion=attributes?EVASION_TABLE[String(Math.floor(attributes.dex))]??null:null;

 return {stats:result,attributes,unknown:[...new Set(unknown)],records,totals,hpParts,skillEffects:activeSkills};
}
function renderCalculatedStatus(){const s=set(),c=char(),calc=calculateStatus(c,s),manual=s.statusMode==='manual',stats=manual?s.stats:calc.stats,fmt=n=>n===null||n===undefined?'—':Number(n).toLocaleString('pt-PT',{maximumFractionDigits:2});$('#stats').innerHTML=`<div class="status-effects">${[['petActive','Contar pet e habilidades'],['alchemyActive','Alquimia ativa']].map(([key,label])=>`<label><input type="checkbox" data-status-effect="${key}" ${s.statusEffects?.[key]?'checked':''} ${readonly||!c.sets.length?'disabled':''}><span>${label}</span></label>`).join('')}<small>Guardado por set · atualiza os status ao selecionar</small></div><div class="status-mode">${manual?'Referência manual':'Calculado · '+(calc.unknown.length?'parcial':'dados configurados')}</div><div class="statgrid">`+Object.entries(statKeys).map(([k,n])=>`<div class="stat"><small>${n}</small><strong>${k==='attack'?(stats.attack===null?'—':fmt(stats.attack)+(stats.attackMax!==stats.attack?'–'+fmt(stats.attackMax):'')):fmt(stats[k])}${['block','crit','pierce','attackSpeed','magicResist','arrowEvade'].includes(k)&&stats[k]!==null?'%':''}</strong>${k==='arrowEvade'?`<span class="stat-secondary">Evasão por DES (painel): ${fmt(calc.stats.evasion)}</span>`:''}${k==='magicResist'?`<span class="stat-secondary">Defesa mágica (valor): ${fmt(calc.stats.magicDefense)}</span>`:''}</div>`).join('')+'</div>'+`<div class="attribute-strip">${Object.entries({int:'INT',vit:'VIT',dex:'DES',str:'FRÇ'}).map(([k,n])=>`<span>${n} <strong>${fmt(calc.attributes?.[k])}</strong></span>`).join('')}<span>Precisão <strong>${fmt(calc.stats.precision)}</strong></span></div>`;$('#resists').innerHTML=elements.map(([k,n,col])=>`<div class="resist"><label>${n}</label><span class="bar"><i style="--tone:${col};width:${Math.min(100,Math.max(0,stats[k]||0))}%"></i></span><strong>${fmt(stats[k])}%</strong></div>`).join('');$('#resists').innerHTML+=`<div class="element-status"><div class="eyebrow sectionlabel">PODER DOS ELEMENTOS</div>${elements.map(([k,n])=>`<div class="element-total element-${k}"><span>${esc(n)}</span><strong>${fmt(calc.totals['power'+k[0].toUpperCase()+k.slice(1)])}%</strong></div>`).join('')}</div>`;$('#statusHint').innerHTML=`${manual?'Totais manuais preservados.':'Atualiza ao mudar equipamentos, bónus, pedras ou gemas. Valores incompletos podem ser subtotais; — indica que falta uma base de cálculo.'}<details class="status-details"><summary>${calc.unknown.length?'Dados a confirmar ('+calc.unknown.length+')':'Ver cálculo e fontes'}</summary>${calc.unknown.length?'<ul>'+calc.unknown.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul>':''}<p>O valor de evasão por DES do painel é distinto do bónus percentual Evitar Flechas; não se somam. A tabela da wiki dá 30 para DES 90–96. <a href="https://it-wiki.metin2.gameforge.com/index.php/Elusione" target="_blank" rel="noopener">Tabela de evasão</a>.</p><p>Defesa % do talismã reduz dano e não aumenta a defesa mostrada. A defesa natural segue a fórmula da wiki italiana (nível + ⌊0,8 × VIT⌋); pode ser confirmada por um valor medido. <a href="https://it-wiki.metin2.gameforge.com/index.php/Difesa" target="_blank" rel="noopener">Fonte de defesa</a>. Defesa mágica (valor) segue LV + VIT/3 + INT + metade da defesa dos equipamentos, com os bónus de defesa mágica; é distinta da resistência percentual a magia. <a href="https://it-wiki.metin2.gameforge.com/index.php/Difesa_Magica" target="_blank" rel="noopener">Fonte de defesa mágica</a>.</p><p>Habilidades: Lâmina = ⌊(3 × INT + 2 × nível) × K⌋; Armadura = ⌊(30 + INT) × K⌋; Receio = ⌊1 + 29 × K⌋%. Usamos a INT total do set atual; no jogo, Lâmina e Armadura conservam a INT no momento da ativação. Reflexão da Armadura não é calculada. <a href="https://it-wiki.metin2.gameforge.com/index.php/Costante_delle_Skill" target="_blank" rel="noopener">Coeficientes</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/Lama_Incantata" target="_blank" rel="noopener">Lâmina</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/Armatura_Incantata" target="_blank" rel="noopener">Armadura</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/Paura" target="_blank" rel="noopener">Receio</a>.</p><p>Configurações por set: pet e alquimia desligados até serem ativados. A montada entra quando a opção Montado está ativa. Buffs, energia, ressonância e efeitos de mapa entram quando registados. Não calcula dano final nem presume buffs por conhecer o nível da skill.</p>${calc.hpParts?`<div class="hp-breakdown"><strong>Composição do HP</strong><p>Inicial ${fmt(calc.hpParts.initial)} + níveis ${fmt(calc.hpParts.growth)} + VIT ${fmt(calc.hpParts.vit)} + Biólogo ${fmt(calc.hpParts.bio)} = base ${fmt(calc.hpParts.natural)}.<br>Base + HP percentual ${fmt(calc.hpParts.percent)} + HP dos itens/efeitos ${fmt(calc.hpParts.flat)} = ${fmt(calc.stats.hp)}.</p></div>`:''}<table><thead><tr><th>Origem</th><th>Atributo</th><th>Valor</th></tr></thead><tbody>${calc.records.map(r=>`<tr><td>${esc(r.source)}</td><td>${esc(r.label)}</td><td>${esc(r.value)}</td></tr>`).join('')}</tbody></table><p><a href="https://gameforge.com/en-GB/games/metin2-faq-leveling.html" target="_blank" rel="noopener">Pontos de atributos</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/HP" target="_blank" rel="noopener">HP</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/Attacco" target="_blank" rel="noopener">Ataque</a> · <a href="https://it-wiki.metin2.gameforge.com/index.php/Missioni_del_Biologo" target="_blank" rel="noopener">Biólogo</a></p></details>`;}
document.addEventListener('click',e=>{if(e.target.closest('#priorityAttrs')){const a=priorityAttributes(char(),$('[name="bubbles"]').value);for(const k of Object.keys(a))$('[name="'+k+'"]').value=a[k];}if(e.target.closest('#manualStatus')){ $('#modal').close();editManualStats(); }});
document.addEventListener('change',e=>{if(['catalogId','upgrade'].includes(e.target.name))syncRefinementEditor(e.target.name==='catalogId');});

document.addEventListener('change',e=>{const key=e.target.dataset?.statusEffect;if(!['petActive','alchemyActive'].includes(key)||readonly||!char().sets.length)return;const s=set();s.statusEffects={...(s.statusEffects||{}),[key]:!!e.target.checked};s.statusMode='auto';save();});

function petSkillEffect(p,name,lv){
 const context=petSkillContext(p),manual=(!p.skillValueContext||p.skillValueContext===context)?p.skillValues?.[name+':'+lv]:undefined;if(manual!==undefined)return {value:Number(manual),origin:'Confirmado no jogo'};
 const species=p.species&&p.species!=='Automático'?p.species:p.name;
 const key=Object.keys(window.PET_SKILL_LEVEL105||{}).find(n=>normalized(n).replace(/[^a-z0-9]/g,'')===normalized(species).replace(/[^a-z0-9]/g,''));
 if(Number(p.level)!==105||Number(lv)!==20||!key)return {value:null,origin:'Sem tabela exata para esta combinação'};
 const raw=window.PET_SKILL_LEVEL105[key][name],type=Number(String(p.type||'').match(/[1-8]/)?.[0]);
 if(key==='Mini Razador'&&type&&name==='Enfurecido')return {value:type<=4?11:13,origin:'Tabela · pet 105 / habilidade 20 / tipo '+type};
 if(key==='Mini Razador'&&type&&name==='Perfuração')return {value:type<=2?11:type<=4?12:13,origin:'Tabela · pet 105 / habilidade 20 / tipo '+type};
 if(key==='Mini Executor Grd'&&type&&name==='Enfurecido')return {value:type<=3?8:type<=6?11:16,origin:'Tabela · pet 105 / habilidade 20 / tipo '+type};
 if(key==='Mini Executor Grd'&&type&&name==='Perfuração')return {value:type<=2?11:type<=4?12:13,origin:'Tabela · pet 105 / habilidade 20 / tipo '+type};
 if(raw&&/^\d+(?:[.,]\d+)?%$/.test(raw))return {value:Number(raw.replace('%','').replace(',','.')),origin:'Tabela · pet 105 / habilidade 20'};
 return {value:null,origin:raw?'Tabela indica '+raw+'; falta confirmar o tipo':'Sem tabela exata para esta combinação'};
}
function alchemySetInfo(c){
 const stones=c.alchemy.stones,configs=stones.slice(0,6).map(g=>gemConfig(g));
 if(stones.length<6||configs.some((cfg,i)=>cfg.cl<0||stones[i].available===false||!gemEntry(stones[i],i)))return {active:false,reason:'Requer as seis pedras originais equipadas e disponíveis.'};
 const cl=configs[0].cl;if(configs.some(cfg=>cfg.cl!==cl))return {active:false,reason:'As seis pedras originais devem ter a mesma classe.'};
 if(![4,5].includes(cl))return {active:false,reason:'Bónus documentados para conjuntos lendário e mítico.'};
 return {active:true,cl,name:cl===5?'Mítico':'Lendário'};
}
function alchemySetLines(c,i){
 const info=alchemySetInfo(c),g=c.alchemy.stones[i];if(!info.active||!g||g.available===false||gemConfig(g).cl!==info.cl||!gemEntry(g,i))return [];
 const myth=info.cl===5,n=myth?3:1;
 const fixed=[['Força: '+n,'Resistência Fogo: '+n+'%'],['Inteligência: '+n,'Resistência Gelo: '+n+'%'],['Máx. MN: '+(myth?150:50),'Resistência Vento: '+n+'%'],['Destreza: '+n,'Resistência Terra: '+n+'%'],['Máx. VD: '+(myth?450:150),'Resistência Relâmpagos: '+n+'%'],['Vitalidade: '+n,'Resistência Trevas: '+n+'%'],['Forte contra Demónios: '+n+'%','Precisão: '+n]];
 const lines=[...fixed[i]];if(myth){if(i<6)lines.push('Poder '+['Fogo','Gelo','Vento','Terra','Raios','Trevas'][i]+': 3%');else lines.push('Vontade de Sung Ma (VIT): 3');}
 const increments=[{b2:myth?'5%':'2%',b3:myth?'5%':'2%',b4:myth?'90':'20',b5:myth?'90':'30'},
 {b2:myth?'5%':'2%',b3:myth?'5%':'2%',b4:myth?'5':'2',b5:myth?'5':'2'},
 {b2:myth?'900':'300',b3:myth?'6%':'2%',b4:myth?'3%':'1%',b5:myth?'2%':'1%',b6:myth?'3%':'1%'},
 {},{b2:myth?'450':'150',b3:myth?'6%':'2%',b4:myth?'3%':'1%',b5:myth?'2%':'1%',b6:myth?'3%':'1%'},
 {b2:n+'%',b3:n+'%',b4:n+'%',b5:n+'%',b6:n+'%'},{str:String(n),res:String(n),int:String(n),metin:(myth?2:1)+'%'}];
 const cat=window.ALCHEMY_CATALOG[alchemyKinds[i]];for(const id of gemChoices(g,i)){const value=i===3?(myth?'5%':'2%'):increments[i][id];if(value&&gemEntry(g,i)?.extra[id])lines.push(cat.labels[id]+': '+value);}
 return lines;
}

function petSkillContext(p){return [p.species&&p.species!=='Automático'?p.species:p.name,Number(p.level),p.type].map(normalized).join('|');}
